class ResourceHolder {
    void* handle;
public:
    ResourceHolder(void* h) : handle(h) {}
    ~ResourceHolder() { free(handle); }

    ResourceHolder(ResourceHolder&& other) noexcept
        : handle(other.handle) // Steal resource
    {
        other.handle = nullptr; // Nullify source
    }

    ResourceHolder& operator=(ResourceHolder&& other) noexcept;
    ResourceHolder(const ResourceHolder&) = delete;
    ResourceHolder& operator=(const ResourceHolder&) = delete;
};

ResourceHolder& ResourceHolder::operator=(ResourceHolder&& other) noexcept {
    if (this != &other) {
        free(handle); // Release current resource

        handle = other.handle; // Steal handle
        other.handle = nullptr;
    }
    return *this;
}

